package com.hosteldekho.controller; import com.hosteldekho.dto.ApiDtos.*; import com.hosteldekho.entity.Enums.BookingStatus; import com.hosteldekho.service.HostelService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/manager") public class ManagerController { final HostelService s; public ManagerController(HostelService x){s=x;} private String e(Authentication a){return (String)a.getPrincipal();}@GetMapping("/hostels") List<HostelDetailDto> mine(Authentication a){return s.mine(e(a));}@PostMapping("/hostels") ResponseEntity<HostelDetailDto> create(Authentication a,@Valid @RequestBody HostelRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(e(a),r));}@PutMapping("/hostels/{id}") HostelDetailDto update(Authentication a,@PathVariable Long id,@Valid @RequestBody HostelRequest r){return s.update(e(a),id,r);}@DeleteMapping("/hostels/{id}") ResponseEntity<Void> delete(Authentication a,@PathVariable Long id){s.delete(e(a),id);return ResponseEntity.noContent().build();}@PostMapping("/hostels/{id}/rooms") ResponseEntity<RoomDto> add(Authentication a,@PathVariable Long id,@Valid @RequestBody RoomRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.addRoom(e(a),id,r));}@PutMapping("/hostels/{hostelId}/rooms/{roomId}") RoomDto updateRoom(Authentication a,@PathVariable Long hostelId,@PathVariable Long roomId,@Valid @RequestBody RoomRequest r){return s.updateRoom(e(a),hostelId,roomId,r);}@PostMapping("/rooms/{roomId}/occupancy") RoomDto occupancy(Authentication a,@PathVariable Long roomId,@Valid @RequestBody OccupancyChangeRequest r){return s.changeOccupancy(e(a),roomId,r.delta());}@PostMapping("/hostels/{id}/rooms/confirm-availability") ResponseEntity<Void> confirmAvailability(Authentication a,@PathVariable Long id){s.confirmAvailability(e(a),id);return ResponseEntity.noContent().build();}@DeleteMapping("/hostels/{hostelId}/rooms/{roomId}") ResponseEntity<Void> deleteRoom(Authentication a,@PathVariable Long hostelId,@PathVariable Long roomId){s.deleteRoom(e(a),hostelId,roomId);return ResponseEntity.noContent().build();}@GetMapping("/booking-requests") List<BookingDto> requests(Authentication a){return s.requests(e(a));}@PutMapping("/booking-requests/{id}/approve") BookingDto approve(Authentication a,@PathVariable Long id){return s.change(e(a),id,BookingStatus.APPROVED);}@PutMapping("/booking-requests/{id}/reject") BookingDto reject(Authentication a,@PathVariable Long id){return s.change(e(a),id,BookingStatus.REJECTED);} }
